    ["<HTML><BODY><H1align=\"center\">ATREATISEONMILITARYRANKS</H1><BR/><BR/><IMGsrc=\"Interface\\PvPRankBadges\\PvPRankAlliance\"align=\"left\"/><BR/><Palign=\"right\">Whatfollowsare</P><Palign=\"right\">themilitaryranks</P><Palign=\"right\">oftheAlliance,</P><Palign=\"right\">proceededbysuch</P><Palign=\"right\">informationasis</P><Palign=\"right\">knownfortheraces</P><Palign=\"right\">oftheHorde.Each</P><Palign=\"right\">ispresentedintwo</P><Palign=\"right\">sections,theofficersandthentheenlisted,withtheranksofeachlistedindescendingorderfromhighesttolowest.LonglivetheAlliance!</P></BODY></HTML>"] = "<HTML>\n<BODY>\n<H1 align=\"center\">EN AFHANDLING OM MILITÆRE RANGER</H1>\n<BR/>\n<BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRankAlliance\" align=\"left\"/>\n<BR/>\n<P align=\"right\">Det følgende er</P>\n<P align=\"right\">de militære ranger</P>\n<P align=\"right\">af Alliancen,</P>\n<P align=\"right\">efterfulgt af sådan</P>\n<P align=\"right\">information som er</P>\n<P align=\"right\">kendt om racerne</P>\n<P align=\"right\">af Horden.  Hver</P>\n<P align=\"right\">præsenteres i to</P>\n<P align=\"right\">afsnit, officererne og derefter de menige, med rangerne i hver liste i faldende orden fra højest til lavest.  Længe leve Alliancen!</P>\n</BODY>\n</HTML>",
