    ["<HTML><BODY><H1align=\"center\">Chapter1:THENORTHERNPYLON</H1><BR/><BR/><IMGsrc=\"Interface\\Pictures\\11482_crystals_mini_north\"align=\"left\"/><Palign=\"right\">TheNorthern<BR/>Pylonaccepts<BR/>yellow,red,<BR/>andgreen<BR/>crystals.</P><BR/><BR/><BR/><BR/><Palign=\"left\">ThePylonfocusesontheenergythatcanbecreatedusingyellowcrystalsasthemainsourceofpower.</P></BODY></HTML>"] = "<HTML>\n<BODY>\n<H1 align=\"center\">\nKapitel 1: DEN NORDLIGE PYLON\n</H1>\n<BR/>\n<BR/>\n<IMG src=\"Interface\\Pictures\\11482_crystals_mini_north\" align=\"left\"/>\n<P align=\"right\">Den Nordlige<BR/>\nPylon accepterer<BR/>\ngule, røde,<BR/>\nog grønne<BR/>\nkrystaller.</P>\n<BR/>\n<BR/>\n<BR/>\n<BR/>\n<P align=\"left\">Pylonen fokuserer på den energi, der kan skabes ved hjælp af gule krystaller som den primære kraftkilde.</P>\n</BODY>\n</HTML>",
