    ["<HTML><BODY><H1align=\"center\">ENLISTEDRANKSOFTHEHORDE</H1><BR/><IMGsrc=\"Interface\\PvPRankBadges\\PvPRank05\"align=\"left\"/><BR/><Palign=\"right\">FirstSergeant</P><BR/><BR/><IMGsrc=\"Interface\\PvPRankBadges\\PvPRank04\"align=\"left\"/><BR/><Palign=\"right\">SeniorSergeant</P><BR/><BR/><IMGsrc=\"Interface\\PvPRankBadges\\PvPRank03\"align=\"left\"/><BR/><Palign=\"right\">Sergeant</P><BR/><BR/><IMGsrc=\"Interface\\PvPRankBadges\\PvPRank02\"align=\"left\"/><BR/><Palign=\"right\">Grunt</P><BR/><BR/><IMGsrc=\"Interface\\PvPRankBadges\\PvPRank01\"align=\"left\"/><BR/><Palign=\"right\">Scout</P><BR/><BR/></BODY></HTML>"] = "<HTML>\n<BODY>\n<H1 align=\"center\">DE MENIGE RANGER I HORDEN</H1><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank05\" align=\"left\"/><BR/>\n<P align=\"right\">Førstesergent</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank04\" align=\"left\"/><BR/>\n<P align=\"right\">Seniorsergent</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank03\" align=\"left\"/><BR/>\n<P align=\"right\">Sergent</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank02\" align=\"left\"/><BR/>\n<P align=\"right\">Fodsoldat</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank01\" align=\"left\"/><BR/>\n<P align=\"right\">Spejder</P><BR/><BR/>\n</BODY>\n</HTML>",
    ["<HTML><BODY><H1align=\"center\">EasternCrystalCombinations</H1><BR/><Palign=\"left\">Therearetwopossibleeffects:oneprovidesbonustospirit,andonethatcreatesadamagingshield.</P><BR/><Palign=\"left\">CRYSTALFORCE:Requiresblueandgreencrystals.<BR/>Thiswillprovideyouwithanincreaseinspirit.</P><BR/><Palign=\"left\">CRYSTALSPIRE:Requiresblueandyellowcrystals.<BR/>Thiswillcreateashieldthatdoesdamagetoattackers.</P></BODY></HTML>"] = "<HTML>\n<BODY>\n<H1 align=\"center\">\nØstlige Krystalkombinationer\n</H1>\n<BR/>\n<P align=\"left\">Der er to mulige effekter: én giver bonus til ånd, og én der skaber et skadende skjold.</P>\n<BR/>\n<P align=\"left\">KRYSTALKRAFT: Kræver blå og grønne krystaller.<BR/>Dette giver dig en øgning af ånd.</P>\n<BR/>\n<P align=\"left\">KRYSTALSPIRET: Kræver blå og gule krystaller.<BR/>Dette skaber et skjold, der gør skade på angribere.\n</P>\n</BODY>\n</HTML>",
    ["<HTML><BODY><H1align=\"center\">HORDEENLISTEDRANKS</H1><BR/><IMGsrc=\"Interface\\PvPRankBadges\\PvPRank05\"align=\"left\"/><BR/><Palign=\"right\">FirstSergeant</P><BR/><BR/><IMGsrc=\"Interface\\PvPRankBadges\\PvPRank04\"align=\"left\"/><BR/><Palign=\"right\">SeniorSergeant</P><BR/><BR/><IMGsrc=\"Interface\\PvPRankBadges\\PvPRank03\"align=\"left\"/><BR/><Palign=\"right\">Sergeant</P><BR/><BR/><IMGsrc=\"Interface\\PvPRankBadges\\PvPRank02\"align=\"left\"/><BR/><Palign=\"right\">Grunt</P><BR/><BR/><IMGsrc=\"Interface\\PvPRankBadges\\PvPRank01\"align=\"left\"/><BR/><Palign=\"right\">Scout</P><BR/><BR/></BODY></HTML>"] = "<HTML>\n<BODY>\n<H1 align=\"center\">HORDENS MENIGE RANGER</H1><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank05\" align=\"left\"/><BR/>\n<P align=\"right\">Førstesergent</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank04\" align=\"left\"/><BR/>\n<P align=\"right\">Seniorsergent</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank03\" align=\"left\"/><BR/>\n<P align=\"right\">Sergent</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank02\" align=\"left\"/><BR/>\n<P align=\"right\">Fodsoldat</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank01\" align=\"left\"/><BR/>\n<P align=\"right\">Spejder</P><BR/><BR/>\n</BODY>\n</HTML>",
    ["<HTML><BODY><H1align=\"center\">HORDEMILITARYRANKS</H1><BR/><Palign=\"center\">OFFICERS</P><BR/><Palign=\"center\">HighWarlord</P><Palign=\"center\">Warlord</P><Palign=\"center\">General</P><Palign=\"center\">LieutenantGeneral</P><Palign=\"center\">Champion</P><Palign=\"center\">Centurion</P><Palign=\"center\">Legionnaire</P><Palign=\"center\">BloodGuard</P><Palign=\"center\">StoneGuard</P><BR/><Palign=\"center\">ENLISTED</P><BR/><Palign=\"center\">FirstSergeant</P><Palign=\"center\">SeniorSergeant</P><Palign=\"center\">Sergeant</P><Palign=\"center\">Grunt</P><Palign=\"center\">Scout</P></BODY></HTML>"] = "<HTML> <BODY> <H1 align=\"center\">HORDENS MILITÆRE GRADER</H1><BR/> <P align=\"center\">OFFICERER</P><BR/> <P align=\"center\">Højkrigsherre</P> <P align=\"center\">Krigsherre</P> <P align=\"center\">General</P> <P align=\"center\">Generalløjtnant</P> <P align=\"center\">Mester</P> <P align=\"center\">Centurion</P> <P align=\"center\">Legionær</P> <P align=\"center\">Blodvagt</P> <P align=\"center\">Stenvagten</P><BR/> <P align=\"center\">HVERVEDE</P><BR/> <P align=\"center\">Førstesergent</P> <P align=\"center\">Seniorsergent</P> <P align=\"center\">Sergent</P> <P align=\"center\">Fodsoldat</P> <P align=\"center\">Spejder</P> </BODY> </HTML>",
    ["<HTML><BODY><H1align=\"center\">MILITARYRANKSOFTHEHORDE&amp;ALLIANCE</H1><BR/><BR/><IMGsrc=\"Interface\\PvPRankBadges\\PvPRankHorde\"align=\"left\"/><BR/><Palign=\"right\">Throm'ka!Inthis</P><Palign=\"right\">bookyouwillfind</P><Palign=\"right\">manylistingsof</P><Palign=\"right\">themilitaryranks</P><Palign=\"right\">oftheHordeand</P><Palign=\"right\">thepunyAlliance.</P><Palign=\"right\">Firstwillcomethe</P><Palign=\"right\">Horde,thentheAlliance,</P><Palign=\"right\">eachwithlistingsofofficersandenlistedranks.Asisfitting,thestrongestarelistedatthetop,withtheweakerlistedbelowthem.</P></BODY></HTML>"] = "<HTML>\n<BODY>\n<H1 align=\"center\">MILITÆRE RANGER FRA HORDEN &amp; ALLIANCEN</H1>\n<BR/>\n<BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRankHorde\" align=\"left\"/>\n<BR/>\n<P align=\"right\">Throm'ka!  I denne</P>\n<P align=\"right\">bog vil du finde</P>\n<P align=\"right\">mange oversigter over</P>\n<P align=\"right\">de militære ranger</P>\n<P align=\"right\">fra Horden og</P>\n<P align=\"right\">den patetiske Alliance.</P>\n<P align=\"right\">Først kommer</P>\n<P align=\"right\">Horden, derefter Alliancen,</P>\n<P align=\"right\">hver med oversigter over officerer og menige ranger.  Som det sig hør og bør, står de stærkeste øverst, med de svagere nedenunder.</P>\n</BODY>\n</HTML>",
    ["<HTML><BODY><H1align=\"center\">NORTHERNPYLONTABLEDIAGRAM</H1><BR/><IMGsrc=\"Interface\\Pictures\\11482_crystals_north\"/></BODY></HTML>"] = "<HTML>\n<BODY>\n<H1 align=\"center\">\nNORDLIG PYLON-BORDDIAGRAM\n</H1>\n<BR/>\n<IMG src=\"Interface\\Pictures\\11482_crystals_north\"/>\n</BODY>\n</HTML>",
    ["<HTML><BODY><H1align=\"center\">NorthernCrystalCombinations</H1><BR/><Palign=\"left\">Therearetwopossibleeffects:onethatwillproducedamage,andonethatwillnegatedamage.</P><BR/><Palign=\"left\">CRYSTALCHARGE:Requiresredandyellowcrystals.<BR/>Thiswillproducealargeexplosion.</P><BR/><Palign=\"left\">CRYSTALRESTORE:Requiresyellowandgreencrystals.<BR/>Thiswillprovideyouwithahealingaura.</P></BODY></HTML>"] = "<HTML>\n<BODY>\n<H1 align=\"center\">\nNordlige Krystalkombinationer\n</H1>\n<BR/>\n<P align=\"left\">Der er to mulige effekter: én der vil forvolde skade, og én der vil negere skade. </P>\n<BR/>\n<P align=\"left\">KRYSTALLADNING: Kræver røde og gule krystaller. <BR/>Dette vil frembringe en stor eksplosion.</P>\n<BR/>\n<P align=\"left\">KRYSTALGENOPRETNING: Kræver gule og grønne krystaller. <BR/>Dette giver dig en helende glorie.\n</P>\n</BODY>\n</HTML>",
