    ["<HTML><BODY><IMGsrc=\"Interface\\Pictures\\Linken_sepia_256px\"/></BODY></HTML>"] = "<HTML>\n<BODY>\n<IMG src=\"Interface\\Pictures\\Linken_sepia_256px\"/>\n</BODY>\n</HTML>",
    ["<Theinkswirlsandshiftsaroundthepage.Yougetthefeelingthatthebookismockingyou.>"] = "<Blækket hvirvler og forskyder sig rundt om siden. Du får en fornemmelse af, at bogen håner dig.>",
    ["<Thepagesarecoveredinancientelvenrunes.>Thepageshereincontainmemoriesofeventsthattranspiredinthecollectionandcreationofthereagentsrequiredtocraftgreaterarcanum.Mayourenemiesnevergainaccesstotheselibram.MayIlivetoseethepallidlightofthemoonshineuponQuel'Thalasonceagain.MayIdiebutforthegraceofKael'thas.MayIkillforthegloryofIllidan.-MasterKarielWinthalus"] = "<Siderne er dækket af gamle runer fra alferne.>\n\nSiderne heri indeholder minder om begivenheder, der fandt sted under indsamlingen og skabelsen af de reagenser, der kræves for at fremstille større arkanum.\n\nMåtte vores fjender aldrig få adgang til denne helligbog. \n\nMåtte jeg leve for at se månens blege lys skinne over Quel'Thalas igen.\n\nMåtte jeg dø, men kun takket være Kael'thas' nåde.\n\nMåtte jeg dræbe til Illidans ære.\n\n-Mester Kariel Vinthalus",
    ["<Thepagesarecoveredinancientelvenrunes.>Thepageshereincontainmemoriesofeventsthattranspiredinthecollectionandcreationofthereagentsrequiredtocraftlesserarcanum.Mayourenemiesnevergainaccesstotheselibram.MayIlivetoseethepallidlightofthemoonshineuponQuel'Thalasonceagain.MayIdiebutforthegraceofKael'thas.MayIkillforthegloryofIllidan.-MasterKarielWinthalus"] = "<Siderne er dækket af gamle runer fra alferne.>\n\nSiderne heri indeholder minder om begivenheder, der fandt sted under indsamlingen og skabelsen af de reagenser, der kræves for at fremstille mindre arkanum.\n\nMåtte vores fjender aldrig få adgang til denne helligbog. \n\nMåtte jeg leve for at se månens blege lys skinne over Quel'Thalas igen.\n\nMåtte jeg dø, men kun takket være Kael'thas' nåde.\n\nMåtte jeg dræbe til Illidans ære.\n\n-Mester Kariel Vinthalus",
    ["<Therestofthebookisblank>"] = "<Resten af bogen er tom>",
    ["<Youcannotunderstandanythingwrittenonthesepages.>"] = "<Du kan ikke forstå noget af det, der står skrevet på disse sider.>",
    ["<Youfeelasearingpainwhenglancingatthesepages.>"] = "<Du mærker en brændende smerte, når du kigger på disse sider.>",
    ["<Youthumbthroughmoreoftheboundpaperandlandonadiagramspreadacrossbothpages.>WeaponsSystemModificationsIceTurret-OperationalFlameThrower-OperationalElectroPulse-OperationalRadiationSpray-OperationalAutoRifle-OperationalLaserCuttingBeam-EXPERIMENTALSonicCannon-EXPERIMENTALPhaseRay-CONCEPTONLYPage34Page35"] = "<Du bladrer igennem mere af det indbundne papir og lander på et diagram, der strækker sig over begge sider.>\r\n\r\nVåbensystemmodifikationer\r\n\r\nIs-tårn - Operationel\r\nFlammekaster - Operationel\r\nElektro-puls - Operationel\r\nStrålingssprøjt - Operationel\r\nAuto-gevær - Operationel\r\nLaserskærende Stråle - EKSPERIMENTEL\r\nSonisk Kanon - EKSPERIMENTEL\r\nFasestråle - KUN KONCEPT\r\n\r\nSide 34                                      Side 35",
    ["<Youtouchthesmallwhitecrystalandyoucanhearfaintsoundsonthewind.Thisisanaudiorecordingofsomesort.>\"AnexcerptfromtheShal'nan'sspeechatthegroundbreakingceremonyfortheShrineoftheFourWinds,ZephrasIsle.\""] = "<Du rører ved den lille hvide krystal, og du kan høre svage lyde i vinden. Dette er en slags lydoptagelse.>\r\n\r\n\"Et uddrag af Shal'nanens tale ved første spadestik for Helligdommen for de Fire Vinde, Vindras-øen.\"",
    ["<Youtouchthesmallwhitecrystalandyoucanhearfaintsoundsonthewind.Thisisanaudiorecordingofsomesort.>\"OnTheWindlord.\""] = "<Du rører ved den lille hvide krystal, og du kan høre svage lyde i vinden. Dette er en slags lydoptagelse.>\r\n\r\n\"Om Vindherren.\"",
    ["<Youtouchthesmallwhitecrystalandyoucanhearfaintsoundsonthewind.Thisisanaudiorecordingofsomesort.>\"TheRebellioninEldre'Thalas,Part1\""] = "<Du rører ved den lille hvide krystal, og du kan høre svage lyde i vinden. Dette er en slags lydoptagelse.>\r\n\r\n\"Oprøret i Eldre'Thalas, Del 1\"",
    ["<Youtouchthesmallwhitecrystalandyoucanhearfaintsoundsonthewind.Thisisanaudiorecordingofsomesort.>\"TheRebellioninEldre'Thalas,Part2\""] = "<Du rører ved den lille hvide krystal, og du kan høre svage lyde i vinden. Dette er en slags lydoptagelse.>\r\n\r\n\"Oprøret i Eldre'Thalas, Del 2\"",
    ["<Youtouchthesmallwhitecrystalandyoucanhearfaintsoundsonthewind.Thisisanaudiorecordingofsomesort.>\"TheRebellioninEldre'Thalas,Part3\""] = "<Du rører ved den lille hvide krystal, og du kan høre svage lyde i vinden. Dette er en slags lydoptagelse.>\r\n\r\n\"Oprøret i Eldre'Thalas, Del 3\"",
